float Pattern( vec2 uv )
{
    //return step(0.,sin(uv.x*60.)+sin(uv.y*60.));

    // circular patterns may help with the motion illusion

    vec2 polar = vec2(atan(uv.x,uv.y),length(uv));
    // polar.x = fract(10.*polar.x/6.283185)*6.283185/10.;

    return step(0.,sin(polar.x*25.)*sin(sqrt(polar.y)*90.));
}

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    fragColour = vec4(0);
    float count = 0.;
    for ( int aa=0; aa < 16; aa++ ) // anti-aliasing
    {
        vec2 jitter = fract(vec2(.754877666247,.569840290998)*float(aa));
        // Normalized pixel coordinates (from 0 to 1)
        vec4 uv;
        uv.xy = (fragCoord+jitter-iResolution.xy*.5)/iResolution.y;

        float a = .01;
        uv.zw = uv.xy*cos(a)+sin(a)*vec2(-1,1)*uv.yx;

        vec2 pattern = vec2(Pattern(uv.xy),Pattern(uv.zw));

        // it's late at night and i can't think clearly enough to make this maths simpler so use a big if
        vec3 col = vec3(.5);
        if ( all( greaterThan( pattern, vec2(0) ) ) ) col = vec3(.6);
        else if ( pattern.x > 0. ) col = vec3(1,1,0);
        else if ( pattern.y > 0. ) col = vec3(0,0,1);
        fragColour.rgb += col;
        count++;
    }
    fragColour.rgb /= count;
    fragColour.a = 1.;
}
